{"content":""""DepGraph dependency resolution engine."""

import base64
import json
import os
import re
from typing import Dict, List


class DependencyConflictError(Exception):
    """Raised when version constraints cannot be satisfied."""


class CircularDependencyError(Exception):
    """Raised when a dependency cycle is detected."""


class PackageNotFoundError(Exception):
    """Raised when a dependency is missing from the registry."""


def _parse_version(version: str):
    """Parse a version string into a comparable tuple.

    Numeric components compare numerically; non-numeric components
    compare as strings. Trailing zero components are stripped so that
    e.g. "1.0" == "1.0.0".
    """
    parts = []
    for piece in str(version).strip().split("."):
        piece = piece.strip()
        if re.fullmatch(r"\d+", piece):
            parts.append(int(piece))
        else:
            # Split leading numeric portion from the rest (e.g. "0rc1").
            m = re.match(r"(\d+)(.*)$", piece)
            if m:
                parts.append(int(m.group(1)))
                if m.group(2):
                    parts.append(m.group(2))
            else:
                parts.append(piece)
    # Strip trailing numeric zeros for equality across lengths.
    while len(parts) > 1 and parts[-1] == 0:
        parts.pop()
    return tuple(parts)


def _compare_versions(v1: str, v2: str) -> int:
    """Return -1 if v1 < v2, 0 if equal, 1 if v1 > v2."""
    t1 = _parse_version(v1)
    t2 = _parse_version(v2)
    n = max(len(t1), len(t2))
    for i in range(n):
        a = t1[i] if i < len(t1) else 0
        b = t2[i] if i < len(t2) else 0
        if type(a) is not type(b):
            # Numeric components sort before string components.
            a_is_num = isinstance(a, int)
            if a_is_num and not isinstance(b, int):
                return -1
            if isinstance(b, int) and not isinstance(a, int):
                return 1
            a, b = str(a), str(b)
        if a < b:
            return -1
        if a > b:
            return 1
    return 0


_CONSTRAINT_RE = re.compile(r"^(==|>=|<=|>|<)?\s*(.+?)\s*$")


def _check_single_constraint(version: str, operator, wanted: str) -> bool:
    cmp = _compare_versions(version, wanted)
    if operator in (None, "", "=="):
        return cmp == 0
    if operator == ">=":
        return cmp >= 0
    if operator == "<=":
        return cmp <= 0
    if operator == ">":
        return cmp > 0
    if operator == "<":
        return cmp < 0
    raise ValueError(f"Unsupported operator: {operator!r}")


def satisfies(version: str, constraint: str) -> bool:
    """Check whether a version satisfies a (possibly compound) constraint.

    Supports operators ==, >=, <=, >, < and comma-separated intersections
    such as ">=1.0, <3.0". A bare version means exact equality; "*" or
    empty means any version.
    """
    if constraint is None:
        return True
    text = str(constraint).strip()
    if text in ("", "*"):
        return True
    for part in text.split(","):
        part = part.strip()
        if not part or part == "*":
            continue
        m = _CONSTRAINT_RE.match(part)
        if not m:
            raise ValueError(f"Invalid version constraint: {part!r}")
        operator, wanted = m.group(1), m.group(2).strip()
        if not wanted:
            raise ValueError(f"Invalid version constraint: {part!r}")
        if not _check_single_constraint(version, operator, wanted):
            return False
    return True


def _decode_manifest(raw: str) -> dict:
    """Decode one manifest file body (base64-encoded JSON)."""
    text = raw.strip()
    try:
        decoded = base64.b64decode(text, validate=False).decode("utf-8")
        return json.loads(decoded)
    except Exception:
        # Lenient fallback: treat the body itself as plain JSON.
        return json.loads(text)


class DependencyResolver:
    """Loads a package registry and resolves dependency graphs."""

    def __init__(self, registry_path: str):
        self.registry_path = registry_path
        self.registry: Dict[str, dict] = {}
        # Backwards-compatible alias.
        self.packages: Dict[str, dict] = self.registry
        if not os.path.isdir(registry_path):
            raise FileNotFoundError(f"Registry directory not found: {registry_path}")
        for filename in sorted(os.listdir(registry_path)):
            if not filename.endswith(".manifest"):
                continue
            filepath = os.path.join(registry_path, filename)
            if not os.path.isfile(filepath):
                continue
            with open(filepath, "r", encoding="utf-8") as fh:
                raw = fh.read()
            if not raw.strip():
                continue
            manifest = _decode_manifest(raw)
            name = manifest.get("name")
            if name is None:
                # Fall back to the file stem: "{package_name}.manifest".
                name = filename[: -len(".manifest")]
            manifest["name"] = name
            manifest.setdefault("version", "0.0.0")
            manifest.setdefault("dependencies", {})
            if manifest["dependencies"] is None:
                manifest["dependencies"] = {}
            self.registry[name] = manifest

    def _load_root_dependencies(self, root_config_path: str) -> Dict[str, str]:
        with open(root_config_path, "r", encoding="utf-8") as fh:
            data = json.load(fh)
        if isinstance(data, dict) and isinstance(data.get("dependencies"), dict):
            return dict(data["dependencies"])
        if isinstance(data, dict):
            # Tolerate {"deps": {...}} alias.
            if isinstance(data.get("deps"), dict):
                return dict(data["deps"])
            # If the whole file is a name->constraint mapping, use it,
            # ignoring non-constraint metadata keys.
            deps = {}
            for key, value in data.items():
                if key in ("name", "version"):
                    continue
                if isinstance(value, str):
                    deps[key] = value
            # A package-like root file without deps yields {}.
            if deps or "dependencies" not in data:
                # Distinguish metadata-only files from dep maps: if every
                # remaining string value parses as a constraint, keep it.
                return deps
            return {}
        return {}

    def resolve(self, root_config_path: str) -> List[Dict]:
        root_deps = self._load_root_dependencies(root_config_path)

        constraints: Dict[str, List[str]] = {}
        for pkg, constr in root_deps.items():
            constraints.setdefault(pkg, []).append(constr)

        order: List[Dict] = []
        state: Dict[str, int] = {}  # 0/ absent = unvisited, 1 = in stack, 2 = done
        stack: List[str] = []

        def visit(pkg: str):
            status = state.get(pkg, 0)
            if status == 2:
                # Already resolved: still validate any newly added constraints.
                manifest = self.registry.get(pkg)
                if manifest is None:
                    raise PackageNotFoundError(
                        f"Package not found in registry: {pkg}"
                    )
                for constr in constraints.get(pkg, []):
                    if not satisfies(manifest["version"], constr):
                        raise DependencyConflictError(
                            f"Version conflict for {pkg}: "
                            f"version {manifest['version']} does not satisfy "
                            f"{constr!r} (all requirements: "
                            f"{constraints.get(pkg, [])})"
                        )
                return
            if status == 1:
                cycle = stack[stack.index(pkg):] + [pkg] if pkg in stack else [pkg, pkg]
                raise CircularDependencyError(
                    "Circular dependency detected: " + " -> ".join(cycle)
                )
            manifest = self.registry.get(pkg)
            if manifest is None:
                raise PackageNotFoundError(
                    f"Package not found in registry: {pkg}"
                )
            for constr in constraints.get(pkg, []):
                if not satisfies(manifest["version"], constr):
                    raise DependencyConflictError(
                        f"Version conflict for {pkg}: "
                        f"version {manifest['version']} does not satisfy "
                        f"{constr!r} (all requirements: "
                        f"{constraints.get(pkg, [])})"
                    )
            state[pkg] = 1
            stack.append(pkg)
            for dep_name, dep_constr in (manifest.get("dependencies") or {}).items():
                constraints.setdefault(dep_name, []).append(dep_constr)
                visit(dep_name)
            stack.pop()
            state[pkg] = 2
            order.append({"name": pkg, "version": manifest["version"]})

        for pkg in list(root_deps.keys()):
            visit(pkg)
        return order
